  {"id":"pulse-ox-1","topic":"Advanced Pulse Oximetry & Plethysmography","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"What physical principle allows pulse oximetry to isolate arterial oxygen saturation?","answer":"Plethysmography identifies arterial pulsations, allowing correction for non-pulsating venous blood and tissue light absorption.","rationale":"The ratio of pulsatile to non-pulsatile light absorption at two wavelengths (660 nm red, 940 nm infrared) corresponds to the oxyhemoglobin/deoxyhemoglobin ratio.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":191}],"confusable_with":""},
  {"id":"pulse-ox-2","topic":"Advanced Pulse Oximetry & Plethysmography","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"A patient has a measured SpO2 of 94% but the actual SaO2 may be falsely high. What could explain this?","answer":"Carboxyhemoglobin (CO poisoning); pulse oximetry cannot distinguish HbCO from oxyHb, causing falsely elevated SpO2 when SaO2 is actually lower.","rationale":"Standard two-wavelength pulse oximetry reads HbCO and oxyHb similarly at 660nm; CO-oximetry on ABG is needed for accurate measurement.","bloom":"analyze","source":[{"book":"Morgan & Mikhail","page":193}],"confusable_with":"Methemoglobin (causes SpO2 to plateau at ~85% regardless of true SaO2)"},
  {"id":"pulse-ox-3","topic":"Advanced Pulse Oximetry & Plethysmography","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"List four causes of pulse oximetry artifact that produce falsely low or inaccurate readings.","answer":"Motion, low perfusion (low CO/hypothermia/vasoconstriction), optical shunting (light bypassing tissue), excessive ambient light, venous pulsations in dependent limbs.","rationale":"These factors interfere with accurate light transmission or introduce non-arterial absorbance; perfusion index and waveform quality should be checked.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":193}],"confusable_with":""},
  {"id":"pulse-ox-4","topic":"Advanced Pulse Oximetry & Plethysmography","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"What is the clinical value of pulse oximetry during esophageal intubation?","answer":"Rapid diagnosis of hypoxia from unrecognized esophageal intubation, enabling early intervention before desaturation becomes severe.","rationale":"SpO2 delay is a limitation, but fall in SpO2 after intubation prompts immediate ETT position verification before cardiac arrest.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":193}],"confusable_with":""},
  {"id":"pulse-ox-5","topic":"Advanced Pulse Oximetry & Plethysmography","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"When light source and detector are on the same side of the tissue (e.g. forehead), what oximetry mode is used?","answer":"Reflectance (backscatter) oximetry; used for forehead sensors when transmittance across the tissue is not possible.","rationale":"Reflectance mode measures backscattered light instead of transmitted light; useful for locations where transillumination is anatomically impossible.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":191}],"confusable_with":"Transmittance oximetry (source and detector opposite each other)"}
